def _live_readiness_precondition(
    *,
    precondition: AdminApiLiveReadinessPrecondition,
    status: AdminApiGateStatus,
    configured: bool,
    source: str,
    expected_source: str,
    detail: str,
    blocker: AdminApiLiveAdmissionBlocker | None = None,
    evidence: list[str] | None = None,
) -> AdminLiveReadinessPreconditionItem:
    blocking = status == AdminApiGateStatus.BLOCKED
    return AdminLiveReadinessPreconditionItem(
        precondition=precondition,
        status=status,
        required=True,
        configured=configured,
        blocking=blocking,
        backend_owned=True,
        route_bound=True,
        source=source,
        expected_source=expected_source,
        blocker=blocker if blocking else None,
        browser_authority="display_only",
        bff_authority="forward_only_no_execution",
        evidence=list(evidence or []),
        detail=detail,
    )


def _live_readiness_preconditions(
    *,
    method: str,
    route: str,
    shared_method: str,
    approval_snapshot: AdminLiveApprovalSnapshotEvidence,
    approval_store_contract: AdminLiveApprovalStoreContractEvidence,
    admission_audit_trail: AdminLiveAdmissionAuditTrailEvidence,
    cap_guard_contract: AdminLiveCapGuardContractEvidence,
    live_execution_adapter: dict[str, Any],
    live_execution_service: dict[str, Any],
) -> list[AdminLiveReadinessPreconditionItem]:
    adapter_configured = bool(live_execution_adapter.get("configured"))
    adapter_source = str(live_execution_adapter.get("source") or "not_configured")
    adapter_reference = str(
        live_execution_adapter.get("adapter_reference")
        or f"AdminApiCommandService.{shared_method}"
    )
    adapter_status = AdminApiGateStatus.PASSED if adapter_configured else AdminApiGateStatus.BLOCKED
    service_status_value = live_execution_service.get(
        "status",
        AdminApiLiveExecutionStatus.LIVE_DISABLED,
    )
    service_configured = (
        service_status_value == AdminApiLiveExecutionStatus.APPROVAL_REQUIRED
        or service_status_value == AdminApiLiveExecutionStatus.APPROVAL_REQUIRED.value
    )
    service_source = str(
        live_execution_service.get("source")
        or DISABLED_LIVE_EXECUTION_SERVICE_SOURCE
    )
    service_status = (
        AdminApiGateStatus.PASSED
        if service_configured
        else AdminApiGateStatus.BLOCKED
    )
    return [
        _live_readiness_precondition(
            precondition=AdminApiLiveReadinessPrecondition.APPROVAL_STORE_CONTRACT,
            status=approval_store_contract.status,
            configured=approval_store_contract.configured,
            source=approval_store_contract.source,
            expected_source="admin_api_approval_store",
            detail=approval_store_contract.detail,
            blocker=(
                None
                if approval_store_contract.configured
                else AdminApiLiveAdmissionBlocker.APPROVAL_STORE_MISSING
            ),
            evidence=approval_store_contract.evidence,
        ),
        _live_readiness_precondition(
            precondition=AdminApiLiveReadinessPrecondition.APPROVAL_SNAPSHOT,
            status=approval_snapshot.status,
            configured=approval_snapshot.present,
            source=approval_snapshot.source,
            expected_source="approval_snapshot",
            detail=approval_snapshot.detail,
            blocker=AdminApiLiveAdmissionBlocker.APPROVAL_SNAPSHOT_MISSING,
            evidence=approval_snapshot.evidence,
        ),
        _live_readiness_precondition(
            precondition=AdminApiLiveReadinessPrecondition.ADMISSION_AUDIT_TRAIL,
            status=admission_audit_trail.status,
            configured=admission_audit_trail.configured,
            source=admission_audit_trail.source,
            expected_source="admin_api_audit_log",
            detail=admission_audit_trail.detail,
            blocker=AdminApiLiveAdmissionBlocker.ADMISSION_AUDIT_MISSING,
            evidence=admission_audit_trail.evidence,
        ),
        _live_readiness_precondition(
            precondition=AdminApiLiveReadinessPrecondition.CAP_GUARD_CONTRACT,
            status=cap_guard_contract.status,
            configured=cap_guard_contract.configured,
            source=cap_guard_contract.source,
            expected_source="guard_risk_policy",
            detail=cap_guard_contract.detail,
            blocker=AdminApiLiveAdmissionBlocker.CAP_GUARD_MISSING,
            evidence=cap_guard_contract.evidence,
        ),
        _live_readiness_precondition(
            precondition=AdminApiLiveReadinessPrecondition.RECONCILIATION_PLAN,
            status=AdminApiGateStatus.BLOCKED,
            configured=False,
            source="not_configured",
            expected_source="reconciliation_policy",
            detail=(
                f"{method} {route} remains live-disabled until a route-specific "
                "post-live reconciliation plan is linked to approval, audit, "
                "and cap/guard evidence."
            ),
            blocker=AdminApiLiveAdmissionBlocker.RECONCILIATION_PLAN_MISSING,
            evidence=[
                "Reconciliation plan proof is required before live execution.",
                "The plan must be route-bound and payload-bound through backend evidence.",
            ],
        ),
        _live_readiness_precondition(
            precondition=AdminApiLiveReadinessPrecondition.LIVE_EXECUTION_ADAPTER,
            status=adapter_status,
            configured=adapter_configured,
            source=adapter_source,
            expected_source=adapter_reference,
            detail=str(live_execution_adapter.get("detail") or ""),
            blocker=(
                None
                if adapter_configured
                else AdminApiLiveAdmissionBlocker.LIVE_EXECUTION_DISABLED
            ),
            evidence=[
                str(item)
                for item in live_execution_adapter.get("evidence", [])
            ],
        ),
        _live_readiness_precondition(
            precondition=AdminApiLiveReadinessPrecondition.EXECUTION_INTENT_ENVELOPE,
            status=AdminApiGateStatus.PASSED,
            configured=True,
            source="command_admission",
            expected_source=adapter_reference,
            detail=(
                f"{method} {route} command admissions expose backend-owned "
                "execution intent evidence, but the intent remains "
                "non-executable while live execution is disabled."
            ),
            evidence=[
                "Execution intent binds route, actor, idempotency key, operator intent, and payload hash.",
                "Intent evidence is display-only and cannot be used by the browser or BFF as execution authority.",
            ],
        ),
        _live_readiness_precondition(
            precondition=AdminApiLiveReadinessPrecondition.BROWSER_BFF_BOUNDARY,
            status=AdminApiGateStatus.PASSED,
            configured=True,
            source="frontend_boundary",
            expected_source="backend_contract",
            detail=(
                "Browser and BFF authority is display-only/forward-only and "
                "cannot satisfy live admission or execute Coinbase orders."
            ),
            evidence=[
                "Browser authority remains display_only.",
                "BFF command forwarding remains forward_only_no_execution.",
            ],
        ),
        _live_readiness_precondition(
            precondition=AdminApiLiveReadinessPrecondition.LIVE_EXECUTION_SERVICE,
            status=service_status,
            configured=service_configured,
            source=service_source,
            expected_source="admin_api_live_execution_service",
            detail=str(live_execution_service.get("detail") or ""),
            blocker=(
                None
                if service_configured
                else AdminApiLiveAdmissionBlocker.LIVE_EXECUTION_DISABLED
            ),
            evidence=[
                "The backend live execution service is intentionally disabled.",
                "No create, cancel, submit, execute, or Coinbase client method is exposed.",
                *[
                    str(item)
                    for item in live_execution_service.get("evidence", [])
                ],
            ],
        ),
    ]


def _path_id(method: str, path: str) -> str:
    normalized = path.strip("/").replace("/", ".").replace("{", "").replace("}", "")
    return f"{method.lower()}.{normalized}"


def _order_item_from_row(
    row: dict[str, Any],
    *,
    expected_client_order_id: str | None = None,
    authoritative_source: Literal["order_parent", "stealth_orders"] = (
        "order_parent"
    ),
) -> AdminOrderReadItem:
    if not isinstance(row, dict):
        raise _OrderProjectionError(BACKEND_ORDER_PROJECTION_INVALID)
    client_order_id = _canonical_public_uuid(
        row.get("client_order_id") or row.get("stealth_order_id")
    )
    if expected_client_order_id is not None:
        expected_id = _canonical_public_uuid(expected_client_order_id)
        if client_order_id != expected_id:
            raise _OrderProjectionError(BACKEND_ORDER_PROJECTION_INVALID)
    last_lifecycle_event = _stealth_lifecycle_event_or_none(
        row.get("last_lifecycle_event")
    )
    try:
        return AdminOrderReadItem(
            client_order_id=client_order_id,
            product_id=_safe_public_order_product(row.get("product_id")),
            side=_known_public_order_value(
                row.get("side"),
                allowed=_KNOWN_PUBLIC_ORDER_SIDES,
            ),
            status=_known_public_order_value(
                row.get("status"),
                allowed=_KNOWN_PUBLIC_ORDER_STATUSES,
            ),
            order_type=_known_public_order_value(
                row.get("order_type"),
                allowed=_KNOWN_PUBLIC_ORDER_TYPES,
            ),
            size=_positive_public_decimal(row.get("size")),
            price=_positive_public_decimal(row.get("price")),
            parent_client_order_id=_canonical_public_uuid(
                row.get("parent_order_id"),
                nullable=True,
            ),
            ownership_provenance=_ownership_provenance_or_none(
                row.get("ownership_provenance")
            ),
            # Durable portfolio binding remains available to backend admission
            # but is not part of ordinary Admin readback.
            retail_portfolio_id=None,
            created_at=_strict_timezone_iso(row.get("created_at")),
            updated_at=_strict_timezone_iso(row.get("updated_at")),
            exchange_order_id=_safe_public_order_evidence(
                row.get("exchange_order_id")
                or row.get("coinbase_order_id")
                or row.get("active_exchange_order_id"),
                max_length=64,
            ),
            correlation_id=_safe_public_order_evidence(
                row.get("correlation_id"),
                max_length=255,
            ),
            audit_id=_safe_public_order_evidence(
                row.get("audit_id"),
                max_length=255,
            ),
            last_lifecycle_event=last_lifecycle_event,
            failure_reason=_public_order_failure_classification(
                row.get("failure_reason"),
                last_lifecycle_event=last_lifecycle_event,
            ),
            source=authoritative_source,
        )
    except ValueError as exc:
        raise _OrderProjectionError(BACKEND_ORDER_PROJECTION_INVALID) from exc


def _opposite_follow_up_side(side: str | None) -> str | None:
    try:
        source_side = OrderSide(str(side or "").upper())
    except ValueError:
        return None
    if source_side == OrderSide.BUY:
        return OrderSide.SELL.value
    if source_side == OrderSide.SELL:
        return OrderSide.BUY.value
    return None


def _runtime_follow_up_claim_state(
    client_order_id: str,
) -> tuple[str | None, str, bool]:
    try:
        bridge = _runtime_bridge()
        engine = getattr(bridge, "order_engine", None) if bridge else None
        orderbook = getattr(engine, "orderbook", None) if engine else None
        claim_state = getattr(orderbook, "follow_up_claim_state", None)
        if not callable(claim_state):
            return None, "runtime_orderbook_unavailable", False
        lock = getattr(engine, "orderbook_lock", None)
        if lock is None:
            return (
                _string_or_none(
                    claim_state(SpotFollowUpTrigger.FILLED.value, client_order_id)
                ),
                "orderbook.follow_up_claim_state",
                True,
            )
        with lock:
            state = claim_state(SpotFollowUpTrigger.FILLED.value, client_order_id)
        return _string_or_none(state), "orderbook.follow_up_claim_state", True
    except Exception as exc:
        return None, f"orderbook.follow_up_claim_state_error:{type(exc).__name__}", False


def _runtime_fill_follow_up_execution_adapter_state() -> tuple[bool, str]:
    try:
        bridge = _runtime_bridge()
        engine = getattr(bridge, "order_engine", None) if bridge else None
        handle_filled_order = getattr(engine, "handle_filled_order", None)
        if not callable(handle_filled_order):
            return False, "runtime_order_engine_handle_filled_order_unavailable"
        return (
            True,
            "dashboard_server.stealth_order_bridge.order_engine.handle_filled_order",
        )
    except Exception as exc:
        return False, f"order_engine.handle_filled_order_error:{type(exc).__name__}"


def _order_follow_up_chain_ids(
    *,
    root_parent_client_order_id: str,
    active_client_order_id: str,
) -> list[str]:
    try:
        from database.order import get_parent_orders

        rows = get_parent_orders() or []
    except Exception:
        return []
    follow_up_ids: list[str] = []
    for row in rows:
        if _string_or_none(row.get("parent_order_id")) != root_parent_client_order_id:
            continue
        candidate_id = _string_or_none(row.get("client_order_id"))
        if not candidate_id or candidate_id in follow_up_ids:
            continue
        if candidate_id == root_parent_client_order_id:
            continue
        follow_up_ids.append(candidate_id)
    if (
        active_client_order_id != root_parent_client_order_id
        and active_client_order_id not in follow_up_ids
    ):
        follow_up_ids.append(active_client_order_id)
    return follow_up_ids


def _durable_automatic_fill_follow_up_ids(
    *,
    root_parent_client_order_id: str,
    product_id: str | None,
    follow_up_side: str | None,
    retail_portfolio_id: str | None,
) -> list[str]:
    """Return the deterministic first Admin fill child across its lifecycle.

    The automatic decision is that the child was created exactly once.  A
    controlled submission and terminal reconciliation must not erase that
    durable decision merely because the same child now has Coinbase identity
    evidence or has advanced from ``PENDING`` to ``OPEN``/``CANCELLED``.
    """

    if not product_id or not follow_up_side or not retail_portfolio_id:
        return []
    expected_first_child_id = str(
        uuid.uuid5(
            uuid.NAMESPACE_URL,
            (
                "coinbase://filled-follow-up/"
                f"{root_parent_client_order_id}/{root_parent_client_order_id}"
            ),
        )
    )
    try:
        from database.order import get_parent_orders

        rows = get_parent_orders() or []
    except Exception:
        return []
    child_ids: list[str] = []
    for row in rows:
        child_id = _string_or_none(row.get("client_order_id"))
        if not child_id or child_id in child_ids:
            continue
        if child_id != expected_first_child_id:
            continue
        if _string_or_none(row.get("parent_order_id")) != (
            root_parent_client_order_id
        ):
            continue
        if _ownership_provenance_or_none(row.get("ownership_provenance")) != (
            OrderOwnershipProvenance.ADMIN_FILL_FOLLOW_UP
        ):
            continue
        if _string_or_none(row.get("product_id")) != product_id:
            continue
        if str(row.get("side") or "").upper() != follow_up_side.upper():
            continue
        if _string_or_none(row.get("retail_portfolio_id")) != (
            retail_portfolio_id
        ):
            continue
        if str(row.get("status") or "").upper() not in {
            "HIDDEN",
            "PENDING",
            "SUBMITTED",
            "SUBMISSION_UNKNOWN",
            "OPEN",
            "FILLED",
            "CANCEL_QUEUED",
            "CANCELLED",
            "EXPIRED",
            "FAILED",
        }:
            continue
        child_ids.append(child_id)
    return child_ids


def _order_fill_follow_up_decision_audit(
    row: dict[str, Any] | None,
    *,
    client_order_id: str,
) -> AdminOrderFillFollowUpDecisionAuditEvidence | None:
    if row is None:
        return None

    source_status = _string_or_none(row.get("status"))
    source_side = _string_or_none(row.get("side"))
    product_id = _string_or_none(row.get("product_id"))
    parent_client_order_id = _string_or_none(row.get("parent_order_id"))
    ownership_provenance = _ownership_provenance_or_none(
        row.get("ownership_provenance")
    )
    admin_manual_root_owned = bool(
        parent_client_order_id is None
        and ownership_provenance
        == OrderOwnershipProvenance.ADMIN_MANUAL_ROOT
    )
    root_parent_client_order_id = parent_client_order_id or client_order_id
    filled_status_observed = str(source_status or "").upper() == "FILLED"
    derived_follow_up_side = _opposite_follow_up_side(source_side)
    claim_state, claim_state_source, claim_reader_ran = (
        _runtime_follow_up_claim_state(client_order_id)
    )
    follow_up_ids = _order_follow_up_chain_ids(
        root_parent_client_order_id=root_parent_client_order_id,
        active_client_order_id=client_order_id,
    )
    execution_adapter_observed, _execution_adapter_source = (
        _runtime_fill_follow_up_execution_adapter_state()
    )
    expected_portfolio_id = _string_or_none(
        os.environ.get("COINBASE_ADMIN_API_SPOT_PORTFOLIO_ID")
    )
    observed_portfolio_id = _string_or_none(row.get("retail_portfolio_id"))
    durable_follow_up_ids = _durable_automatic_fill_follow_up_ids(
        root_parent_client_order_id=root_parent_client_order_id,
        product_id=product_id,
        follow_up_side=derived_follow_up_side,
        retail_portfolio_id=observed_portfolio_id,
    )

    policy_allowed: bool | None = None
    policy_intent: str | None = None
    policy_reason: str | None = None
    product_type: str | None = None
    policy_evaluation_ran = False
    blockers = [
        "fill_follow_up_reconciliation_proof_missing",
    ]
    if not execution_adapter_observed:
        blockers.insert(0, "fill_follow_up_execution_adapter_missing")
    if not filled_status_observed:
        blockers.insert(0, "source_order_not_filled")
    if not product_id:
        blockers.insert(0, "product_id_missing")
    if not source_side:
        blockers.insert(0, "source_side_missing")
    if not derived_follow_up_side:
        blockers.insert(0, "follow_up_side_unresolved")
    if not admin_manual_root_owned:
        blockers.insert(0, "admin_manual_root_ownership_provenance_missing")

    if product_id and source_side and derived_follow_up_side:
        policy_evaluation_ran = True
        try:
            decision = evaluate_spot_follow_up_policy(
                product_id=product_id,
                source_side=source_side,
                follow_up_side=derived_follow_up_side,
                trigger=SpotFollowUpTrigger.FILLED,
            )
            policy_allowed = decision.allowed
            policy_intent = decision.intent
            policy_reason = decision.reason
            product_type = decision.product_type
            if not decision.allowed:
                blockers.insert(0, "spot_follow_up_policy_blocked")
        except Exception as exc:
            blockers.insert(
                0,
                f"spot_follow_up_policy_unavailable:{type(exc).__name__}",
            )
            policy_reason = _value_blind_exception_detail(exc)

    durable_automatic_completion = bool(
        admin_manual_root_owned
        and filled_status_observed
        and product_id == "BTC-USDC"
        and policy_allowed is True
        and expected_portfolio_id is not None
        and observed_portfolio_id == expected_portfolio_id
        and len(durable_follow_up_ids) == 1
        and durable_follow_up_ids == follow_up_ids
    )
    if durable_automatic_completion and claim_state is None:
        claim_state = "done"
        claim_state_source = "order_parent.durable_admin_fill_follow_up"
        claim_reader_ran = True
    if durable_automatic_completion:
        blockers = [
            blocker
            for blocker in blockers
            if blocker != "fill_follow_up_execution_adapter_missing"
        ]

    eligible_no_live = filled_status_observed and policy_allowed is True
    automatic_processing_blockers: list[str] = []
    if not execution_adapter_observed and not durable_automatic_completion:
        automatic_processing_blockers.append(
            "fill_follow_up_execution_adapter_missing"
        )
    if not admin_manual_root_owned:
        automatic_processing_blockers.append(
            "admin_manual_root_ownership_provenance_missing"
        )
    if expected_portfolio_id is None:
        automatic_processing_blockers.append("spot_test_portfolio_id_missing")
    elif observed_portfolio_id != expected_portfolio_id:
        automatic_processing_blockers.append(
            "owned_order_portfolio_scope_mismatch"
        )
    if not filled_status_observed:
        automatic_processing_blockers.append("source_order_not_filled")
    if policy_allowed is not True:
        automatic_processing_blockers.append("spot_follow_up_policy_blocked")
    automatic_processing_enabled = not automatic_processing_blockers
    if not automatic_processing_enabled:
        automatic_processing_blockers.insert(
            0,
            "automatic_fill_event_processing_not_enabled",
        )

    if (
        automatic_processing_enabled
        and claim_state == "done"
        and follow_up_ids
    ):
        follow_up_decision = "automatic_child_created"
    elif automatic_processing_enabled and claim_state == "processing":
        follow_up_decision = "automatic_processing"
    elif automatic_processing_enabled:
        follow_up_decision = "automatic_eligible"
    else:
        follow_up_decision = (
            "eligible_no_live" if eligible_no_live else "blocked_no_live"
        )
    return AdminOrderFillFollowUpDecisionAuditEvidence(
        client_order_id=client_order_id,
        ownership_provenance=ownership_provenance,
        status=(
            AdminApiGateStatus.PASSED
            if follow_up_decision == "automatic_child_created"
            else AdminApiGateStatus.BLOCKED
        ),
        source_order_status=source_status,
        filled_status_observed=filled_status_observed,
        trigger=SpotFollowUpTrigger.FILLED.value,
        source_side=source_side,
        derived_follow_up_side=derived_follow_up_side,
        product_id=product_id,
        product_type=product_type,
        policy_evaluation_ran=policy_evaluation_ran,
        policy_allowed=policy_allowed,
        policy_intent=policy_intent,
        policy_reason=policy_reason,
        follow_up_decision=follow_up_decision,
        root_parent_client_order_id=root_parent_client_order_id,
        parent_client_order_id=parent_client_order_id,
        existing_follow_up_client_order_ids=follow_up_ids,
        existing_follow_up_count=len(follow_up_ids),
        flat_hierarchy_enforced=True,
        chain_source="order_parent",
        automation_mode=(
            "automatic_owned_root_fill_event"
            if automatic_processing_enabled
            else "manual_no_live_trigger_only"
        ),
        manual_trigger_route=FILL_FOLLOW_UP_TRIGGER_ROUTE,
        automatic_fill_event_processing_enabled=automatic_processing_enabled,
        automatic_fill_event_processing_status=(
            "enabled" if automatic_processing_enabled else "blocked"
        ),
        automatic_fill_event_processing_blockers=automatic_processing_blockers,
        duplicate_claim_protection_required=True,
        claim_state=claim_state,
        claim_state_source=claim_state_source,
        claim_reader_ran=claim_reader_ran,
        claim_acquired=claim_state in {"processing", "done"},
        order_engine_handle_filled_order_called=False,
        stealth_create_follow_up_called=False,
        follow_up_order_created=False,
        coinbase_order_submit_ran=False,
        coinbase_order_cancel_submitted=False,
        live_coinbase_read_ran=False,
        local_state_mutated=False,
        exchange_state_mutated=False,
        read_evidence_routes=[
            "/api/v1/orders/{client_order_id}",
            "/api/v1/orders/{client_order_id}/fill-readback",
            "/api/v1/orders/{client_order_id}/fill-follow-up/replay",
            "/api/v1/orders/{client_order_id}/fill-follow-up/live-readiness",
            "/api/v1/orders/{client_order_id}/fill-follow-up/chain",
            "/api/v1/stealth/orders/{stealth_order_id}",
            "/api/v1/admin/fill-ledger-health",
        ],
        required_contracts=[
            "fill_follow_up_event_replay_contract",
            "fill_follow_up_duplicate_claim_guard_readback",
            "fill_follow_up_parent_child_chain_readback",
            "fill_follow_up_execution_adapter",
            "fill_follow_up_reconciliation_proof",
            "fill_follow_up_live_scope_approval",
        ],
        missing_contracts=[
            *(
                []
                if execution_adapter_observed
                else ["fill_follow_up_execution_adapter"]
            ),
            "fill_follow_up_reconciliation_proof",
            "fill_follow_up_live_scope_approval",
        ],
        blockers=blockers,
        browser_authority="display_only",
        bff_authority="forward_only_no_execution",
        detail=(
            "Read-only evidence confirms the profile-bound runtime supports "
            "automatic owned-order FILLED processing through the canonical "
            "exactly-once claim and hidden-child persistence path. This read "
            "did not call the engine or mutate local/exchange state."
            if automatic_processing_enabled
            else (
                "Order detail exposes fill-triggered follow-up decision "
                "evidence only. Automatic processing is fail-closed until "
                "the canonical runtime, Test portfolio scope, FILLED status, "
                "and Spot follow-up policy all match. This read did not call "
                "the engine or mutate local/exchange state."
            )
        ),
    )


def _order_fill_follow_up_live_readback_proof_ref(
    *,
    mvp_service: Any | None,
    client_order_id: str,
) -> str | None:
    service = mvp_service
    if service is None:
        try:
            from application.admin_api.mvp_service import get_admin_mvp_service

            service = get_admin_mvp_service()
        except Exception:
            return None
    latest_proof = getattr(service, "latest_spot_fill_readback_proof", None)
    if not callable(latest_proof):
        return None
    try:
        record = latest_proof(client_order_id)
    except Exception:
        return None
    if not isinstance(record, dict):
        return None
    return _string_or_none(
        record.get("live_fill_readback_proof_ref") or record.get("proof_ref")
    )


def _order_fill_follow_up_rollback_readback_ref(
    *,
    spot_recovery_execution_store: FileSpotRecoveryExecutionJournalStore,
    client_order_id: str,
) -> str | None:
    try:
        records = spot_recovery_execution_store.read_for_client_order_id(
            client_order_id,
            limit=50,
        )
    except Exception:
        return None
    for record in records:
        if (
            record.mutation_family
            != AdminApiMutationFamilyType.SPOT_RECOVERY_ROLLBACK_EXECUTION
        ):
            continue
        if (
            _string_or_none(record.route)
            != "/api/v1/spot/recovery/rollback-executions"
        ):
            continue
        if _string_or_none(record.service_method) != "execute_spot_recovery_rollback":
            continue
        if not record.execution_journal_accepted or not record.rollback_journal_accepted:
            continue
        if (
            record.coinbase_order_submitted
            or record.coinbase_rest_read_ran
            or record.live_exchange_submitted
            or record.live_coinbase_orders_ran
        ):
            continue
        if (
            record.order_state_mutated
            or record.exchange_state_mutated
            or record.reconciliation_executed
        ):
            continue
        journal_id = _string_or_none(record.journal_id)
        if journal_id:
            return f"spot_recovery_rollback_journal:{journal_id}"
    return None


def _fill_follow_up_trigger_approval_matches(
    record: AdminApiApprovalRecord,
    *,
    approval_store: FileAdminApiApprovalStore,
    client_order_id: str,
) -> bool:
    try:
        expired = record.is_expired()
    except Exception:
        return False
    if expired:
        return False
    try:
        revoked = approval_store.approval_is_revoked(record.approval_id)
    except Exception:
        return False
    return (
        not revoked
        and record.route == FILL_FOLLOW_UP_TRIGGER_ROUTE
        and record.method.upper() == FILL_FOLLOW_UP_TRIGGER_METHOD
        and record.module_id == FILL_FOLLOW_UP_TRIGGER_MODULE_ID
        and record.identity_key == "client_order_id"
        and record.identity_value == client_order_id
        and _record_text(record.action_class)
        == AdminApiActionClass.LOCAL_STATE_MUTATION.value
        and _record_text(record.required_permission)
        == AdminApiPermission.ORDER_CREATE.value
        and bool(_string_or_none(record.operator_intent))
        and bool(_string_or_none(record.idempotency_key))
        and bool(_string_or_none(record.payload_hash))
        and bool(_string_or_none(record.cap_guard_decision_ref))
        and bool(_string_or_none(record.reconciliation_plan_ref))
    )


def _fill_follow_up_trigger_audit_matches(
    audit: AdminApiAuditEvent | None,
) -> bool:
    if audit is None:
        return False
    decision = audit.admission_decision
    return (
        decision is not None
        and audit.endpoint
        in {
            FILL_FOLLOW_UP_TRIGGER_ROUTE,
            FILL_FOLLOW_UP_TRIGGER_ENDPOINT,
        }
        and audit.client_order_id == decision.identity_value
        and audit.live_exchange_submitted is False
        and audit.live_coinbase_orders_ran is False
        and decision.live_exchange_submitted is False
        and decision.route == FILL_FOLLOW_UP_TRIGGER_ROUTE
        and decision.method.upper() == FILL_FOLLOW_UP_TRIGGER_METHOD
        and decision.module_id == FILL_FOLLOW_UP_TRIGGER_MODULE_ID
        and decision.identity_key == "client_order_id"
        and _record_text(decision.action_class)
        == AdminApiActionClass.LOCAL_STATE_MUTATION.value
        and _record_text(decision.required_permission)
        == AdminApiPermission.ORDER_CREATE.value
        and decision.service_method == FILL_FOLLOW_UP_TRIGGER_SERVICE_METHOD
    )


def _fill_follow_up_trigger_cap_guard_matches(
    record: CapGuardDecisionRecord | None,
    *,
    approval: AdminApiApprovalRecord,
    audit: AdminApiAuditEvent,
    client_order_id: str,
) -> bool:
    if record is None:
        return False
    return (
        record.decision_id == approval.cap_guard_decision_ref
        and record.route == FILL_FOLLOW_UP_TRIGGER_ROUTE
        and record.method.upper() == FILL_FOLLOW_UP_TRIGGER_METHOD
        and record.module_id == FILL_FOLLOW_UP_TRIGGER_MODULE_ID
        and record.identity_key == "client_order_id"
        and record.identity_value == client_order_id
        and _record_text(record.action_class)
        == AdminApiActionClass.LOCAL_STATE_MUTATION.value
        and _record_text(record.required_permission)
        == AdminApiPermission.ORDER_CREATE.value
        and record.service_method == FILL_FOLLOW_UP_TRIGGER_SERVICE_METHOD
        and record.actor_id == approval.requested_by_actor_id
        and record.operator_intent == approval.operator_intent
        and record.idempotency_key == approval.idempotency_key
        and record.payload_hash == approval.payload_hash
        and record.approval_snapshot_id == approval.approval_id
        and record.admission_audit_id == audit.audit_id
        and record.allowed is True
        and _record_text(record.status) == AdminApiGateStatus.PASSED.value
    )


def _fill_follow_up_trigger_wallet_ref(
    record: CapGuardDecisionRecord | None,
) -> str | None:
    if record is None:
        return None
    if record.wallet_check_required is not True:
        return None
    if _record_text(record.wallet_check_status) != AdminApiGateStatus.PASSED.value:
        return None
    if _record_decimal(record.wallet_available_notional_usdc) <= Decimal("0"):
        return None
    if _record_text(record.wallet_check_source) in {"", "missing"}:
        return None
    return f"cap_guard_wallet:{record.decision_id}"


def _fill_follow_up_trigger_reconciliation_matches(
    record: ReconciliationPlanRecord | None,
    *,
    approval: AdminApiApprovalRecord,
    audit: AdminApiAuditEvent,
    cap_guard: CapGuardDecisionRecord,
    client_order_id: str,
) -> bool:
    if record is None:
        return False
    return (
        record.plan_id == approval.reconciliation_plan_ref
        and record.route == FILL_FOLLOW_UP_TRIGGER_ROUTE
        and record.method.upper() == FILL_FOLLOW_UP_TRIGGER_METHOD
        and record.module_id == FILL_FOLLOW_UP_TRIGGER_MODULE_ID
        and record.identity_key == "client_order_id"
        and record.identity_value == client_order_id
        and _record_text(record.action_class)
        == AdminApiActionClass.LOCAL_STATE_MUTATION.value
        and _record_text(record.required_permission)
        == AdminApiPermission.ORDER_CREATE.value
        and record.service_method == FILL_FOLLOW_UP_TRIGGER_SERVICE_METHOD
        and record.actor_id == approval.requested_by_actor_id
        and record.operator_intent == approval.operator_intent
        and record.idempotency_key == approval.idempotency_key
        and record.payload_hash == approval.payload_hash
        and record.approval_snapshot_id == approval.approval_id
        and record.admission_audit_id == audit.audit_id
        and record.cap_guard_decision_id == cap_guard.decision_id
        and record.allowed is True
        and _record_text(record.status) == AdminApiGateStatus.PASSED.value
        and record.exchange_submission_required is False
    )


def _order_fill_follow_up_trigger_proof_refs(
    *,
    approval_store: FileAdminApiApprovalStore,
    audit_store: FileAdminApiAuditStore,
    cap_guard_store: FileAdminApiCapGuardStore,
    reconciliation_store: FileAdminApiReconciliationStore,
    client_order_id: str,
) -> dict[str, str | bool | None]:
    refs: dict[str, str | bool | None] = {
        "fill_testing_approval_present": False,
        "wallet_proof_ref": None,
        "cap_guard_decision_ref": None,
        "reconciliation_plan_ref": None,
    }
    try:
        approvals = approval_store.read_recent(limit=500)
    except Exception:
        return refs

    for approval in approvals:
        if not _fill_follow_up_trigger_approval_matches(
            approval,
            approval_store=approval_store,
            client_order_id=client_order_id,
        ):
            continue
        refs["fill_testing_approval_present"] = True
        try:
            audit = audit_store.find_matching_admission_audit(
                request=AdmissionAuditTrailRequest(
                    route=FILL_FOLLOW_UP_TRIGGER_ROUTE,
                    method=FILL_FOLLOW_UP_TRIGGER_METHOD,
                    module_id=FILL_FOLLOW_UP_TRIGGER_MODULE_ID,
                    identity_key="client_order_id",
                    identity_value=client_order_id,
                    action_class=AdminApiActionClass.LOCAL_STATE_MUTATION,
                    required_permission=AdminApiPermission.ORDER_CREATE,
                    service_method=FILL_FOLLOW_UP_TRIGGER_SERVICE_METHOD,
                    actor_id=approval.requested_by_actor_id,
                    operator_intent=approval.operator_intent,
                    idempotency_key=approval.idempotency_key,
                    payload_hash=approval.payload_hash,
                    approval_snapshot_id=approval.approval_id,
                )
            )
        except Exception:
            return refs
        if not _fill_follow_up_trigger_audit_matches(audit):
            return refs
        try:
            cap_guard = cap_guard_store.find_by_decision_id(
                approval.cap_guard_decision_ref
            )
        except Exception:
            return refs
        if not _fill_follow_up_trigger_cap_guard_matches(
            cap_guard,
            approval=approval,
            audit=audit,
            client_order_id=client_order_id,
        ):
            return refs
        refs["cap_guard_decision_ref"] = cap_guard.decision_id
        wallet_ref = _fill_follow_up_trigger_wallet_ref(cap_guard)
        if wallet_ref:
            refs["wallet_proof_ref"] = wallet_ref
        try:
            reconciliation = reconciliation_store.find_by_plan_id(
                approval.reconciliation_plan_ref
            )
        except Exception:
            return refs
        if _fill_follow_up_trigger_reconciliation_matches(
            reconciliation,
            approval=approval,
            audit=audit,
            cap_guard=cap_guard,
            client_order_id=client_order_id,
        ):
            refs["reconciliation_plan_ref"] = reconciliation.plan_id
        return refs
    return refs


def _json_object_or_none(value: Any) -> dict[str, Any] | None:
    if value is None:
        return None
    if isinstance(value, dict):
        return dict(value)
    if isinstance(value, str):
        stripped = value.strip()
        if not stripped:
            return None
        try:
            parsed = json.loads(stripped)
        except json.JSONDecodeError:
            return {"raw": value}
        return parsed if isinstance(parsed, dict) else {"value": parsed}
    return {"value": value}


_PRIVATE_ANCHOR_REPRICING_STATE_KEYS = frozenset(
    {
        "child_portfolio_ids",
        "child_portfolio_uuids",
        "expected_portfolio_id",
        "expected_portfolio_uuid",
        "observed_portfolio_id",
        "observed_portfolio_uuid",
        "parent_row_id",
        "portfolio_id",
        "portfolio_uuid",
        "profile_id",
        "retail_portfolio_id",
        "retail_portfolio_uuid",
        "root_portfolio_id",
        "root_portfolio_uuid",
    }
)


def _public_anchor_repricing_state(value: Any) -> Any:
    """Recursively remove backend-only binding fields from anchor evidence."""

    if isinstance(value, dict):
        return {
            key: _public_anchor_repricing_state(child)
            for key, child in value.items()
            if str(key) not in _PRIVATE_ANCHOR_REPRICING_STATE_KEYS
        }
    if isinstance(value, list):
        return [_public_anchor_repricing_state(child) for child in value]
    return value


def _json_list(value: Any) -> list[dict[str, Any]]:
    if value is None:
        return []
    if isinstance(value, list):
        return [
            dict(item) if isinstance(item, dict) else {"value": item}
            for item in value
        ]
    if isinstance(value, str):
        stripped = value.strip()
        if not stripped:
            return []
        try:
            parsed = json.loads(stripped)
        except json.JSONDecodeError:
            return [{"raw": value}]
        if isinstance(parsed, list):
            return [
                dict(item) if isinstance(item, dict) else {"value": item}
                for item in parsed
            ]
        return [{"value": parsed}]
    return [{"value": value}]


def _stealth_item_from_row(row: dict[str, Any]) -> AdminStealthOrderReadItem:
    revealed_orders = _json_list(row.get("revealed_orders"))
    internal_anchor_state = (
        _json_object_or_none(row.get("anchor_repricing_state_json")) or {}
    )
    active_placement_client_order_id = _string_or_none(
        internal_anchor_state.get("active_placement_client_order_id")
        or internal_anchor_state.get("active_placement_order_id")
        or internal_anchor_state.get("active_placed_order_id")
    )
    active_exchange_order_id = _string_or_none(
        internal_anchor_state.get("active_exchange_order_id")
    )
    return AdminStealthOrderReadItem(
        stealth_order_id=str(row.get("stealth_order_id") or ""),
        parent_stealth_order_id=_string_or_none(row.get("parent_order_id")),
        product_id=_string_or_none(row.get("product_id")),
        side=_string_or_none(row.get("side")),
        status=_string_or_none(row.get("status")),
        total_size=_string_or_none(row.get("total_size")),
        revealed_size=_string_or_none(row.get("revealed_size")),
        remaining_size=_string_or_none(row.get("remaining_size")),
        executed_size=_string_or_none(row.get("executed_size")),
        limit_price=_string_or_none(row.get("limit_price")),
        target_movement=_string_or_none(row.get("target_movement")),
        target_movement_type=_string_or_none(row.get("target_movement_type")),
        visibility_score=_string_or_none(row.get("visibility_score")),
        reveal_condition_type=_string_or_none(row.get("reveal_condition_type")),
        reveal_condition=_json_object_or_none(row.get("reveal_condition_json")),
        sizing_strategy=_json_object_or_none(row.get("sizing_strategy_json")),
        revealed_orders=revealed_orders,
        active_placement_client_order_id=active_placement_client_order_id,
        active_exchange_order_id=active_exchange_order_id,
        last_placement_at=_string_or_none(row.get("last_placement_at")),
        last_lifecycle_event=_string_or_none(row.get("last_lifecycle_event")),
        failure_reason=_string_or_none(row.get("failure_reason")),
        cancel_reentry_policy=_json_object_or_none(row.get("cancel_reentry_policy_json")),
        cancel_reentry_state=_json_object_or_none(row.get("cancel_reentry_state_json")),
        post_fill_retreat_policy=_json_object_or_none(row.get("post_fill_retreat_policy_json")),
        anchor_repricing_policy=_json_object_or_none(row.get("anchor_repricing_policy_json")),
        anchor_repricing_state=_public_anchor_repricing_state(
            internal_anchor_state
        ),
        created_at=_string_or_none(row.get("created_at")),
        updated_at=_string_or_none(row.get("updated_at")),
    )


def _stealth_active_placement_audit(
    item: AdminStealthOrderReadItem,
) -> AdminStealthActivePlacementAuditEvidence:
    active_placement_present = bool(item.active_placement_client_order_id)
    required_contracts = [
        "stealth_active_placement_exchange_truth_snapshot_contract",
        "stealth_active_placement_exchange_truth_proof_contract",
        "stealth_active_placement_cancel_replace_audit",
        "stealth_active_placement_reconciliation_proof",
    ]
    blockers = [
        "coinbase_exchange_truth_read_disabled",
        "stealth_active_placement_cancel_replace_audit_missing",
        "stealth_active_placement_reconciliation_proof_missing",
    ]
    if not active_placement_present:
        blockers.insert(0, "active_placement_local_evidence_missing")

    detail = (
        "Active placement evidence is local stealth state only. It can explain "
        "why cancel, move, and reprice remain blocked, but it does not verify "
        "Coinbase exchange truth, cancel or replace orders, or allow lifecycle "
        "mutation."
    )
    return AdminStealthActivePlacementAuditEvidence(
        stealth_order_id=item.stealth_order_id,
        status=AdminApiGateStatus.BLOCKED,
        active_placement_present=active_placement_present,
        active_placement_client_order_id=item.active_placement_client_order_id,
        active_exchange_order_id=item.active_exchange_order_id,
        exchange_order_id_evidence_only=True,
        exchange_truth_verified=False,
        exchange_truth_source="local_stealth_state_only",
        coinbase_read_required=True,
        coinbase_read_ran=False,
        coinbase_order_cancel_submitted=False,
        lifecycle_mutation_allowed=False,
        required_for_mutation_families=[
            AdminApiMutationFamilyType.STEALTH_CANCEL,
            AdminApiMutationFamilyType.STEALTH_MOVE,
            AdminApiMutationFamilyType.MOVEMENT_REPRICE,
        ],
        read_evidence_routes=[
            "/api/v1/stealth/orders/{stealth_order_id}",
            (
                "/api/v1/stealth/orders/{stealth_order_id}/active-placement/"
                "exchange-truth-proof"
            ),
            "/api/v1/stealth/command-suite",
        ],
        required_contracts=required_contracts,
        missing_contracts=required_contracts,
        blockers=blockers,
        browser_authority="display_only",
        bff_authority="forward_only_no_execution",
        detail=detail,
    )


def _stealth_mutation_claim_audit(
    stealth_order_id: str,
) -> AdminStealthMutationClaimAuditEvidence:
    claims = _runtime_mutation_claims_for(stealth_order_id)
    runtime_claims_observed = any(claim.runtime_observed for claim in claims)
    active_claim_count = sum(1 for claim in claims if claim.state == "processing")
    claim_reader_source = (
        claims[0].source if claims else "runtime_stealth_manager_unavailable"
    )
    required_contracts = [
        "stealth_move_mutation_claim_snapshot_contract",
        "stealth_reprice_cooldown_claim_contract",
    ]
    blockers = [
        "stealth_move_mutation_claim_snapshot_contract_missing",
        "stealth_reprice_cooldown_claim_contract_missing",
    ]
    if not runtime_claims_observed:
        blockers.insert(0, "runtime_mutation_claim_snapshot_unavailable")

    return AdminStealthMutationClaimAuditEvidence(
        stealth_order_id=stealth_order_id,
        status=AdminApiGateStatus.BLOCKED,
        runtime_claims=claims,
        runtime_claims_observed=runtime_claims_observed,
        runtime_claim_count=len(claims),
        active_claim_count=active_claim_count,
        claim_reader_source=claim_reader_source,
        claim_reader_ran=claim_reader_source != "runtime_stealth_manager_unavailable",
        coinbase_read_ran=False,
        coinbase_order_cancel_submitted=False,
        lifecycle_mutation_allowed=False,
        required_for_mutation_families=[
            AdminApiMutationFamilyType.STEALTH_MOVE,
            AdminApiMutationFamilyType.MOVEMENT_REPRICE,
        ],
        read_evidence_routes=[
            "/api/v1/stealth/orders/{stealth_order_id}",
            "/api/v1/movement-repricing/stealth/{stealth_order_id}",
            "/api/v1/stealth/command-suite",
        ],
        required_contracts=required_contracts,
        missing_contracts=list(required_contracts),
        blockers=blockers,
        browser_authority="display_only",
        bff_authority="forward_only_no_execution",
        detail=(
            "Mutation-claim audit reuses the existing runtime claim reader as "
            "local evidence only. It does not acquire or release claims, call "
            "Coinbase, execute cancel/replace, mutate lifecycle state, or "
            "authorize browser/BFF execution."
        ),
    )


def _stealth_reveal_trigger_audit(
    item: AdminStealthOrderReadItem,
) -> AdminStealthRevealTriggerAuditEvidence:
    required_contracts = ["stealth_reveal_trigger_guard"]
    reveal_condition_present = bool(
        item.reveal_condition_type or item.reveal_condition
    )
    blockers = ["stealth_reveal_trigger_guard_missing"]
    if not reveal_condition_present:
        blockers.insert(0, "reveal_condition_local_evidence_missing")

    return AdminStealthRevealTriggerAuditEvidence(
        stealth_order_id=item.stealth_order_id,
        status=AdminApiGateStatus.BLOCKED,
        reveal_condition_present=reveal_condition_present,
        reveal_condition_type=item.reveal_condition_type,
        reveal_condition=item.reveal_condition,
        trigger_state_source="local_stealth_row_only",
        trigger_evaluation_ran=False,
        should_trigger_reveal_called=False,
        reveal_order_slice_called=False,
        coinbase_order_submit_ran=False,
        lifecycle_mutation_allowed=False,
        required_for_mutation_families=[AdminApiMutationFamilyType.STEALTH_REVEAL],
        read_evidence_routes=[
            "/api/v1/stealth/orders/{stealth_order_id}",
            "/api/v1/stealth/command-suite",
        ],
        required_contracts=required_contracts,
        missing_contracts=list(required_contracts),
        blockers=blockers,
        browser_authority="display_only",
        bff_authority="forward_only_no_execution",
        detail=(
            "Reveal-trigger audit reports local reveal condition evidence only. "
            "It does not evaluate live triggers, call should_trigger_reveal, "
            "call reveal_order_slice, submit Coinbase orders, mutate lifecycle "
            "state, or authorize browser/BFF execution."
        ),
    )


def _stealth_reveal_submission_audit(
    item: AdminStealthOrderReadItem,
) -> AdminStealthRevealSubmissionAuditEvidence:
    required_contracts = [
        "stealth_reveal_exchange_submission_adapter",
        "stealth_reveal_reconciliation_proof",
    ]
    existing_active_placement_present = bool(item.active_placement_client_order_id)
    blockers = [
        "stealth_reveal_exchange_submission_adapter_missing",
        "stealth_reveal_reconciliation_proof_missing",
        "live_execution_disabled",
    ]
    if existing_active_placement_present:
        blockers.insert(0, "existing_active_placement_local_evidence_present")

    return AdminStealthRevealSubmissionAuditEvidence(
        stealth_order_id=item.stealth_order_id,
        status=AdminApiGateStatus.BLOCKED,
        command_route="/api/v1/stealth/orders/{stealth_order_id}/reveal",
        service_method="reveal_stealth_order_by_stealth_order_id",
        reveal_manager_method="core/stealth_order_manager.py::reveal_order_slice",
        submission_adapter_configured=False,
        route_bound=True,
        backend_owned=True,
        existing_active_placement_present=existing_active_placement_present,
        active_placement_client_order_id=item.active_placement_client_order_id,
        active_exchange_order_id=item.active_exchange_order_id,
        exchange_order_id_evidence_only=True,
        reveal_order_slice_called=False,
        coinbase_order_submit_ran=False,
        coinbase_order_cancel_submitted=False,
        live_coinbase_read_ran=False,
        active_placement_created=False,
        lifecycle_mutation_allowed=False,
        reconciliation_required=True,
        reconciliation_executed=False,
        required_for_mutation_families=[AdminApiMutationFamilyType.STEALTH_REVEAL],
        read_evidence_routes=[
            "/api/v1/stealth/orders/{stealth_order_id}",
            "/api/v1/stealth/command-suite",
        ],
        required_contracts=required_contracts,
        missing_contracts=list(required_contracts),
        blockers=blockers,
        browser_authority="display_only",
        bff_authority="forward_only_no_execution",
        detail=(
            "Reveal submission-adapter audit maps the future backend-owned "
            "reveal path and local active-placement evidence only. It does "
            "not call reveal_order_slice, submit Coinbase orders, cancel "
            "placements, create active placements, mutate lifecycle state, "
            "execute reconciliation, or authorize browser/BFF execution."
        ),
    )


def _stealth_reveal_reconciliation_audit(
    item: AdminStealthOrderReadItem,
) -> AdminStealthRevealReconciliationAuditEvidence:
    required_contracts = ["stealth_reveal_reconciliation_proof"]
    blockers = [
        "stealth_reveal_reconciliation_proof_missing",
        "coinbase_exchange_truth_read_disabled",
    ]
    if not item.active_placement_client_order_id:
        blockers.insert(0, "active_placement_local_evidence_missing")

    return AdminStealthRevealReconciliationAuditEvidence(
        stealth_order_id=item.stealth_order_id,
        status=AdminApiGateStatus.BLOCKED,
        command_route="/api/v1/stealth/orders/{stealth_order_id}/reveal",
        reconciliation_required=True,
        reconciliation_plan_required=True,
        reconciliation_proof_required=True,
        reconciliation_plan_resolved=False,
        reconciliation_proof_resolved=False,
        reconciliation_plan_id=None,
        reconciliation_proof_id=None,
        active_placement_client_order_id=item.active_placement_client_order_id,
        active_exchange_order_id=item.active_exchange_order_id,
        exchange_order_id_evidence_only=True,
        coinbase_read_ran=False,
        reconciliation_executed=False,
        order_state_mutated=False,
        lifecycle_mutation_allowed=False,
        post_submit_reconciliation_satisfied=False,
        required_for_mutation_families=[AdminApiMutationFamilyType.STEALTH_REVEAL],
        read_evidence_routes=[
            "/api/v1/stealth/orders/{stealth_order_id}",
            "/api/v1/stealth/command-suite",
            "/api/v1/admin/reconciliation/plans",
        ],
        required_contracts=required_contracts,
        missing_contracts=list(required_contracts),
        blockers=blockers,
        browser_authority="display_only",
        bff_authority="forward_only_no_execution",
        detail=(
            "Reveal reconciliation audit reports missing backend-owned "
            "post-submit reconciliation proof for the reveal workflow. It "
            "does not read Coinbase, resolve reconciliation plans, write "
            "proof records, execute reconciliation, mutate order or lifecycle "
            "state, or authorize browser/BFF reveal execution."
        ),
    )


def _stealth_create_lifecycle_write_audit(
    *,
    required_gate_chain: list[str],
    missing_gate_chain: list[str],
    proof_routes: list[StealthCommandSuiteProofRouteItem],
) -> StealthCreateLifecycleWriteAuditEvidence:
    required_contracts = [
        "stealth_create_guard_contract",
        "stealth_create_admission_audit",
        "stealth_create_reconciliation_plan",
        "stealth_create_lifecycle_write_guard_proof",
        "stealth_create_lifecycle_write_execution_contract",
    ]
    blockers = [
        "stealth_create_lifecycle_write_guard_proof_missing",
        "stealth_create_lifecycle_write_execution_contract_missing",
        "stealth_create_guard_contract_missing",
        "stealth_create_admission_audit_missing",
        "stealth_create_reconciliation_plan_missing",
        "live_execution_disabled",
    ]
    return StealthCreateLifecycleWriteAuditEvidence(
        accepted_command_identity_keys=["stealth_order_id"],
        rejected_command_identity_keys=[
            "client_order_id",
            "active_placement_client_order_id",
            "exchange_order_id",
            "order_id",
        ],
        read_evidence_routes=[
            "/api/v1/stealth/orders",
            "/api/v1/stealth/orders/{stealth_order_id}/lifecycle-write-guard-proof",
            "/api/v1/stealth/command-suite",
            "/api/v1/admin/reconciliation/plans",
        ],
        lifecycle_write_contract_configured=True,
        required_contracts=required_contracts,
        missing_contracts=list(required_contracts),
        blockers=blockers,
        required_gate_chain=list(required_gate_chain),
        missing_gate_chain=list(missing_gate_chain),
        execution_contract=build_stealth_create_lifecycle_write_execution_contract(
            stealth_order_id=None,
            exact_command_context_present=False,
        ),
        proof_route_count=len(proof_routes),
        blocking_proof_route_count=sum(1 for route in proof_routes if route.blocking),
        proof_routes=proof_routes,
        evidence=[
            "Stealth create is exposed as a live-disabled Admin API command draft.",
            "Future execution must call the existing StealthOrderManager create path.",
            "This audit does not write stealth rows, order_parent rows, lifecycle events, or reconciliation evidence.",
            "This audit does not create approval, admission-audit, cap/guard, or reconciliation proof records.",
            "Browser and BFF surfaces remain display/forward only and cannot grant lifecycle-write authority.",
        ],
        detail=(
            "Create lifecycle-write evidence is read-only command-suite "
            "evidence. It records the missing backend contracts required "
            "before POST /api/v1/stealth/orders can invoke the existing "
            "StealthOrderManager create path or mutate local lifecycle state."
        ),
    )


def _int_or_none(value: Any) -> int | None:
    if value is None:
        return None
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def _bool_or_none(value: Any) -> bool | None:
    if value is None:
        return None
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        normalized = value.strip().lower()
        if normalized in {"1", "true", "yes"}:
            return True
        if normalized in {"0", "false", "no"}:
            return False
    return bool(value)


def _list_or_empty(value: Any) -> list[Any]:
    if value is None:
        return []
    if isinstance(value, list):
        return list(value)
    return [value]


def _dict_or_empty(value: Any) -> dict[str, Any]:
    return dict(value) if isinstance(value, dict) else {}


def _runtime_order_engine() -> Any | None:
    bridge = _runtime_bridge()
    return getattr(bridge, "order_engine", None) if bridge else None


def _runtime_orderbook() -> Any | None:
    engine = _runtime_order_engine()
    orderbook = getattr(engine, "orderbook", None) if engine else None
    if orderbook is not None:
        return orderbook
    try:
        import configuration

        orderbook_proxy = getattr(configuration, "ORDERBOOK", None)
        return getattr(orderbook_proxy, "_real", None)
    except Exception:
        return None


def _dashboard_state_snapshot() -> dict[str, Any]:
    try:
        import dashboard_server

        engine_state = getattr(dashboard_server, "engine_state", None)
        state_lock = getattr(dashboard_server, "state_lock", None)
        if not isinstance(engine_state, dict) or state_lock is None:
            return {}
        with state_lock:
            return deepcopy(engine_state)
    except Exception:
        return {}


def _orderbook_product_metadata(orderbook: Any | None) -> dict[str, dict[str, Any]]:
    products = getattr(orderbook, "products", None)
    if products is None:
        products = getattr(orderbook, "product", None)
    if not isinstance(products, dict) and not hasattr(products, "items"):
        return {}
    metadata: dict[str, dict[str, Any]] = {}
    try:
        for product_id, payload in products.items():
            metadata[str(product_id)] = _dict_or_empty(payload)
    except Exception:
        return {}
    return metadata


def _products_json_metadata() -> dict[str, dict[str, Any]]:
    products_path = ROOT / "products.json"
    try:
        payload = json.loads(products_path.read_text(encoding="utf-8"))
    except Exception:
        return {}
    metadata = payload.get("metadata")
    if not isinstance(metadata, dict):
        return {}
    items: dict[str, dict[str, Any]] = {}
    for product_id, product_payload in metadata.items():
        item = _dict_or_empty(product_payload)
        if "product_type" not in item and "type" in item:
            item["product_type"] = item.get("type")
        item.setdefault("product_id", product_id)
        items[str(product_id)] = item
    return items


def _normalize_admin_product_type(
    product_id: str,
    product_metadata: dict[str, Any] | None,
) -> str:
    try:
        from calculation.resolver import normalize_product_type

        return normalize_product_type(
            {
                "product_id": product_id,
                "product_type": _dict_or_empty(product_metadata).get("product_type")
                or _dict_or_empty(product_metadata).get("type"),
            },
            products={product_id: _dict_or_empty(product_metadata)}
            if product_metadata
            else None,
        )
    except Exception:
        return ProductType.FUTURE.value if product_id.endswith("-CDE") else ProductType.SPOT.value


def _futures_product_metadata() -> dict[str, dict[str, Any]]:
    orderbook = _runtime_orderbook()
    metadata = _products_json_metadata()
    metadata.update(_orderbook_product_metadata(orderbook))
    return {
        product_id: payload
        for product_id, payload in metadata.items()
        if _normalize_admin_product_type(product_id, payload) == ProductType.FUTURE.value
    }


def _runtime_fee_info(product_id: str | None = None) -> dict[str, Any]:
    engine = _runtime_order_engine()
    fee_manager = getattr(engine, "fee_manager", None) if engine else None
    if fee_manager is not None:
        try:
            return _dict_or_empty(fee_manager.get_fee_info(product_id=product_id))
        except TypeError:
            try:
                return _dict_or_empty(fee_manager.get_fee_info())
            except Exception:
                pass
        except Exception:
            pass
    dashboard_snapshot = _dashboard_state_snapshot()
    engine_status = _dict_or_empty(dashboard_snapshot.get("engine_status"))
    return {
        key: engine_status.get(key)
        for key in (
            "margin_window_type",
            "overnight_margin_active",
            "effective_fee_rate",
            "target_movement_factor",
            "fee_regime_factor",
            "volume_ratio",
        )
        if key in engine_status
    }


def _snapshot_future_positions() -> tuple[dict[str, dict[str, Any]], AdminFuturesEvidenceSource]:
    orderbook = _runtime_orderbook()
    if orderbook is not None:
        try:
            snapshot = orderbook.snapshot_positions()
            futures_positions = _dict_or_empty(snapshot.get(ProductType.FUTURE.value))
            return {
                str(product_id): _dict_or_empty(position)
                for product_id, position in futures_positions.items()
            }, AdminFuturesEvidenceSource.RUNTIME_ORDERBOOK
        except Exception:
            pass
        try:
            items = orderbook.iter_future_positions()
            return {
                str(product_id): _dict_or_empty(position)
                for product_id, position in items
            }, AdminFuturesEvidenceSource.RUNTIME_ORDERBOOK
        except Exception:
            pass
    dashboard_snapshot = _dashboard_state_snapshot()
    positions = _dict_or_empty(dashboard_snapshot.get("positions"))
    if positions:
        products = _futures_product_metadata()
        filtered_positions: dict[str, dict[str, Any]] = {}
        for product_id, position in positions.items():
            normalized_product_id = str(product_id)
            normalized_position = _dict_or_empty(position)
            if normalized_product_id in products or (
                _normalize_admin_product_type(
                    normalized_product_id,
                    normalized_position,
                )
                == ProductType.FUTURE.value
            ):
                filtered_positions[normalized_product_id] = normalized_position
        return filtered_positions, AdminFuturesEvidenceSource.DASHBOARD_ENGINE_STATE
    return {}, AdminFuturesEvidenceSource.RUNTIME_UNAVAILABLE


def _decimal_string_or_none(value: Any) -> str | None:
    if value is None:
        return None
    return str(value)


def _numeric_float_or_none(value: Any) -> float | None:
    if value is None:
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _position_key(product_id: str, position: dict[str, Any]) -> str:
    """Return a deterministic opaque token without embedding portfolio identity."""

    portfolio_identity = (
        _string_or_none(position.get("portfolio_uuid"))
        or _string_or_none(position.get("portfolio_id"))
        or _string_or_none(position.get("retail_portfolio_id"))
        or "local-runtime-single-profile"
    )
    return opaque_futures_position_key(
        product_id=product_id,
        portfolio_identity=portfolio_identity,
    )


def _futures_position_item_from_raw(
    *,
    product_id: str,
    position: dict[str, Any],
    product_metadata: dict[str, Any] | None,
    mandatory_fee_per_contract: str | None,
    source: AdminFuturesEvidenceSource,
) -> AdminFuturesPositionReadItem:
    return AdminFuturesPositionReadItem.model_validate(
        project_futures_position(
            product_id=product_id,
            position=position,
            product_metadata=product_metadata,
            mandatory_fee_per_contract=mandatory_fee_per_contract,
            source=source,
        )
    )


def _mandatory_fee_map(orderbook: Any | None) -> dict[str, dict[str, Any]]:
    fees = getattr(orderbook, "mandatory_fee_per_contract", None)
    if not isinstance(fees, dict) and not hasattr(fees, "items"):
        return {}
    try:
        return {
            str(product_id): _dict_or_empty(payload)
            for product_id, payload in fees.items()
        }
    except Exception:
        return {}


def _futures_position_items() -> list[AdminFuturesPositionReadItem]:
    products = _futures_product_metadata()
    positions, source = _snapshot_future_positions()
    orderbook = _runtime_orderbook()
    mandatory_fees = _mandatory_fee_map(orderbook)
    items: list[AdminFuturesPositionReadItem] = []
    for product_id, position in positions.items():
        product_metadata = products.get(product_id, {})
        metadata_product_type = _normalize_admin_product_type(
            product_id,
            product_metadata,
        ) if product_metadata else None
        position_product_type = _normalize_admin_product_type(product_id, position)
        if metadata_product_type and metadata_product_type != ProductType.FUTURE.value:
            continue
        if (
            not metadata_product_type
            and source == AdminFuturesEvidenceSource.DASHBOARD_ENGINE_STATE
            and position_product_type != ProductType.FUTURE.value
        ):
            continue
        fee_payload = mandatory_fees.get(product_id, {})
        try:
            item = _futures_position_item_from_raw(
                product_id=product_id,
                position=position,
                product_metadata=product_metadata,
                mandatory_fee_per_contract=fee_payload.get(
                    "mandatory_fee_per_contract"
                ),
                source=source,
            )
        except (FuturesPublicProjectionError, ValueError):
            continue
        items.append(item)
    return items


def _futures_evidence(
    *,
    name: str,
    status: AdminFuturesEvidenceStatus,
    source: AdminFuturesEvidenceSource,
    value: Any | None = None,
    detail: str | None = None,
) -> AdminFuturesEvidenceItem:
    # Rich backend evidence stays internal.  Public reads expose only the fixed
    # availability/source classification, never arbitrary values or detail.
    _ = (value, detail)
    return AdminFuturesEvidenceItem.model_validate(
        public_futures_evidence(
            name=name,
            status=status,
            source=source,
            value=value,
        )
    )


