        def blocker_closure(
            *,
            closure_id: str,
            blocker: AdminApiStealthCommandSuiteBlockerClosure,
            category: AdminApiLivePreflightCategory,
            affected_families: list[AdminApiStealthCommandSuiteGapFamily],
            affected_mutation_families: list[AdminApiMutationFamilyType],
            command_routes: list[str],
            source_evidence_refs: list[str],
            partial_evidence_refs: list[str] | None = None,
            partial_evidence_contracts: list[str] | None = None,
            partial_evidence_detail: str | None = None,
            closure_readiness_criteria: list[str] | None = None,
            closure_readiness_verification_gates: list[str] | None = None,
            closure_readiness_blockers: list[str] | None = None,
            closure_readiness_detail: str | None = None,
            required_backend_contracts: list[str],
            required_proof_routes: list[str],
            required_gate_chain: list[str],
            next_backend_step: str,
            detail: str,
        ) -> StealthCommandSuiteBlockerClosureItem:
            criteria = closure_readiness_criteria or []
            verification_gates = closure_readiness_verification_gates or []
            readiness_blockers = closure_readiness_blockers or []
            trace_source_refs = [
                *source_evidence_refs,
                *(partial_evidence_refs or []),
                *(partial_evidence_contracts or []),
            ]
            backend_contract_dependency_refs = required_backend_contracts
            proof_route_dependency_refs = required_proof_routes
            gate_chain_dependency_refs = required_gate_chain
            dependency_refs = [
                *backend_contract_dependency_refs,
                *proof_route_dependency_refs,
                *gate_chain_dependency_refs,
            ]

            def dependency_clearance_plan_rows() -> list[
                StealthCommandSuiteClosureDependencyClearancePlanRow
            ]:
                rows: list[StealthCommandSuiteClosureDependencyClearancePlanRow] = []
                clearance_step_review_names = {
                    AdminApiStealthClosureClearanceStepName.IMPLEMENT_BACKEND_CONTRACT: (
                        AdminApiStealthClosureClearanceStepReviewName.REVIEW_BACKEND_CONTRACT
                    ),
                    AdminApiStealthClosureClearanceStepName.ADD_PROOF_ROUTE: (
                        AdminApiStealthClosureClearanceStepReviewName.REVIEW_PROOF_ROUTE
                    ),
                    AdminApiStealthClosureClearanceStepName.VERIFY_GATE_CHAIN: (
                        AdminApiStealthClosureClearanceStepReviewName.REVIEW_GATE_CHAIN
                    ),
                }
                clearance_step_review_input_names = {
                    AdminApiStealthClosureClearanceStepReviewName.REVIEW_BACKEND_CONTRACT: (
                        AdminApiStealthClosureClearanceStepReviewInputName.BACKEND_CONTRACT_ARTIFACT
                    ),
                    AdminApiStealthClosureClearanceStepReviewName.REVIEW_PROOF_ROUTE: (
                        AdminApiStealthClosureClearanceStepReviewInputName.PROOF_ROUTE_ARTIFACT
                    ),
                    AdminApiStealthClosureClearanceStepReviewName.REVIEW_GATE_CHAIN: (
                        AdminApiStealthClosureClearanceStepReviewInputName.GATE_CHAIN_EVIDENCE
                    ),
                }
                dependency_groups = [
                    (
                        AdminApiStealthClosureDependencyClass.BACKEND_CONTRACT,
                        AdminApiStealthClosureClearanceOwner.ADMIN_API_CONTRACT,
                        AdminApiStealthClosureClearanceStepName.IMPLEMENT_BACKEND_CONTRACT,
                        backend_contract_dependency_refs,
                    ),
                    (
                        AdminApiStealthClosureDependencyClass.PROOF_ROUTE,
                        AdminApiStealthClosureClearanceOwner.ADMIN_API_CONTRACT,
                        AdminApiStealthClosureClearanceStepName.ADD_PROOF_ROUTE,
                        proof_route_dependency_refs,
                    ),
                    (
                        AdminApiStealthClosureDependencyClass.GATE_CHAIN,
                        AdminApiStealthClosureClearanceOwner.BACKEND_GATE_CHAIN,
                        AdminApiStealthClosureClearanceStepName.VERIFY_GATE_CHAIN,
                        gate_chain_dependency_refs,
                    ),
                ]
                ordered_dependency_refs = [
                    ref
                    for (
                        _dependency_class,
                        _clearance_owner,
                        _clearance_step_name,
                        refs,
                    ) in dependency_groups
                    for ref in refs
                ]

                def remediation_ref_for_dependency(dependency_ref: str) -> str:
                    return (
                        f"{dependency_ref}::clearance_step_review_input"
                        "::store_requirement::record_contract"
                        "::record_validation::remediation"
                    )

                def remediation_dependency_ref_for_dependency(
                    dependency_ref: str,
                ) -> str:
                    return f"{remediation_ref_for_dependency(dependency_ref)}::dependency"

                for (
                    dependency_class,
                    clearance_owner,
                    clearance_step_name,
                    refs,
                ) in dependency_groups:
                    for dependency_ref in refs:
                        clearance_order = len(rows) + 1
                        step_ref = f"{dependency_ref}::clearance_step"
