                        record_contract_ref = (
                            f"{store_requirement_ref}::record_contract"
                        )
                        record_validation_ref = (
                            f"{record_contract_ref}::record_validation"
                        )
                        required_record_schema_ref = (
                            f"{store_requirement_ref}::record_schema"
                        )
